 identity_value jsonb:='{}';key_field text;before_values jsonb;after_values jsonb;
 claims jsonb:=coalesce(nullif(current_setting('request.jwt.claims',true),'')::jsonb,'{}');
 headers jsonb:=coalesce(nullif(current_setting('request.headers',true),'')::jsonb,'{}');
begin
 if tg_table_schema<>'public' or tg_table_name<>all(array['catalog_packaging_documents','catalog_packaging_candidates','catalog_packaging_links']) or pg_trigger_depth()<1 then raise exception 'Audit consentito solo dai trigger delle confezioni';end if;
 if tg_op='UPDATE' then previous:=old.manual_overrides;prior_row:=to_jsonb(old);end if;
 select array_agg(k order by k) into changed from jsonb_object_keys(new.manual_overrides)k where not(previous ? k) or previous->k is distinct from new.manual_overrides->k;
 if changed is null then return new;end if;
 foreach key_field in array tg_argv loop identity_value:=identity_value||jsonb_build_object(key_field,current_row->key_field);end loop;
 select coalesce(jsonb_object_agg(k,prior_row->k),'{}'),coalesce(jsonb_object_agg(k,current_row->k),'{}') into before_values,after_values from unnest(changed)k;
 insert into public.catalog_manual_history(table_name,record_key,changed_fields,before_values,after_values,previous_overrides,new_overrides,actor_role,actor_subject,reason)
 values(tg_table_name,identity_value,changed,before_values,after_values,previous,new.manual_overrides,
  coalesce(claims->>'role',nullif(current_setting('role',true),'none'),session_user::text),claims->>'sub',headers->>'x-catalog-write-reason');
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.bindex_export_page(kind text DEFAULT 'cards'::text, after_time timestamp with time zone DEFAULT '1970-01-01 00:00:00+00'::timestamp with time zone, after_key jsonb DEFAULT '[]'::jsonb, until_time timestamp with time zone DEFAULT NULL::timestamp with time zone, page_size integer DEFAULT 1000)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare cap integer:=least(greatest(coalesce(page_size,1000),1),1000); cutoff timestamptz:=least(coalesce(until_time,statement_timestamp()-interval '1 minute'),statement_timestamp()-interval '1 minute'); result jsonb;
begin
 if kind not in ('cards','sets','photos') or kind is null then raise exception 'Tipo di esportazione non valido';end if;
 if after_key is null or jsonb_typeof(after_key)<>'array' then raise exception 'Cursore non valido';end if;
 if jsonb_array_length(after_key) not in (0,case kind when 'cards' then 3 when 'sets' then 1 else 4 end) then raise exception 'Chiave del cursore incompleta';end if;
 if after_time is null then raise exception 'Timestamp del cursore mancante';end if;
 if kind='cards' then
  with page as materialized (
   select sigla,numero,variante,nome,rarita,codice,cardmarket_id,cardmarket_url,immagine,immagine_hd,tag,aggiornato_il,eliminata,jsonb_build_array(sigla,numero,variante) __key from public.set_carte
   where (aggiornato_il>after_time or (aggiornato_il=after_time and (sigla,numero,variante)>(coalesce(after_key->>0,''),coalesce((after_key->>1)::integer,0),coalesce(after_key->>2,'')))) and aggiornato_il<=cutoff
   order by aggiornato_il,sigla,numero,variante limit cap
  ) select jsonb_build_object('contract','bindex-v1','kind',kind,'until',cutoff,'items',coalesce((select jsonb_agg(to_jsonb(p)-'__key' order by aggiornato_il,sigla,numero,variante) from page p),'[]'::jsonb),
   'next_cursor',(select jsonb_build_object('time',aggiornato_il,'key',__key) from page order by aggiornato_il desc,sigla desc,numero desc,variante desc limit 1),
   'complete',(select count(*)<cap from page)) into result;
 end if;
 if kind='sets' then
  with page as materialized (
   select sigla,tcgdex_id,nome,carte_base,carte_totali,data_uscita,lingua,aggiornato_il,jsonb_build_array(sigla) __key from public.set_espansioni
   where (aggiornato_il>after_time or (aggiornato_il=after_time and sigla>coalesce(after_key->>0,''))) and aggiornato_il<=cutoff
   order by aggiornato_il,sigla limit cap
  ) select jsonb_build_object('contract','bindex-v1','kind',kind,'until',cutoff,'items',coalesce((select jsonb_agg(to_jsonb(p)-'__key' order by aggiornato_il,sigla) from page p),'[]'::jsonb),
   'next_cursor',(select jsonb_build_object('time',aggiornato_il,'key',__key) from page order by aggiornato_il desc,sigla desc limit 1),
   'complete',(select count(*)<cap from page)) into result;
 end if;
 if kind='photos' then
  with page as materialized (
   select sigla,numero,variante,lingua,immagine,immagine_hd,fonte,aggiornato_il,jsonb_build_array(sigla,numero,variante,lingua) __key from public.set_carte_immagini
   where (aggiornato_il>after_time or (aggiornato_il=after_time and (sigla,numero,variante,lingua)>(coalesce(after_key->>0,''),coalesce((after_key->>1)::integer,0),coalesce(after_key->>2,''),coalesce(after_key->>3,'')))) and aggiornato_il<=cutoff
   order by aggiornato_il,sigla,numero,variante,lingua limit cap
  ) select jsonb_build_object('contract','bindex-v1','kind',kind,'until',cutoff,'items',coalesce((select jsonb_agg(to_jsonb(p)-'__key' order by aggiornato_il,sigla,numero,variante,lingua) from page p),'[]'::jsonb),
   'next_cursor',(select jsonb_build_object('time',aggiornato_il,'key',__key) from page order by aggiornato_il desc,sigla desc,numero desc,variante desc,lingua desc limit 1),
   'complete',(select count(*)<cap from page)) into result;
 end if;
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.bindex_guard_reviewed_code()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare reviewed text;
begin
 select r.proposed_code into reviewed from public.catalog_code_reviews r where (r.sigla,r.numero,r.variante)=(old.sigla,old.numero,old.variante) and r.status='verified';
 new.codice:=coalesce(reviewed,new.codice,old.codice);
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.bindex_stable_row()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if tg_op='DELETE' then raise exception 'Le identità pubblicate non si cancellano: usare eliminata=true per le carte o svuotare il contenuto della foto.';end if;
 if tg_op='UPDATE' then
  if new.sigla<>old.sigla then raise exception 'Chiave Bindex immutabile';end if;
  if tg_table_name<>'set_espansioni' then
   if new.numero<>old.numero or new.variante<>old.variante then raise exception 'Chiave Bindex immutabile';end if;
  end if;
  if tg_table_name='set_carte_immagini' then
   if new.lingua<>old.lingua then raise exception 'Lingua della foto immutabile';end if;
  end if;
  if (to_jsonb(new)-'aggiornato_il')=(to_jsonb(old)-'aggiornato_il') then return null;end if;
  new.aggiornato_il:=greatest(clock_timestamp(),old.aggiornato_il+interval '1 microsecond');
 else new.aggiornato_il:=clock_timestamp();end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.catalog_entry_cardmarket()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare source_id text; product_id bigint; published_id bigint; published_url text;
begin
 source_id:=case when new.verification<>'catalog' then new.source_payload->'variant'->'thirdParty'->>'cardmarket' end;
 if source_id ~ '^[1-9][0-9]{0,9}$' then product_id:=source_id::bigint;end if;
 select c.cardmarket_id,c.cardmarket_url into published_id,published_url
 from public.catalog_export_links l join public.set_carte c using(sigla,numero,variante)
 where l.entry_key=new.entry_key and not c.eliminata;
 new.cardmarket_id:=null;new.cardmarket_url:=null;new.cardmarket_method:=null;new.cardmarket_status:='pending';
 if product_id is not null and published_id is not null and product_id<>published_id then
  new.cardmarket_status:='conflict';return new;
 end if;
 new.cardmarket_id:=coalesce(published_id,product_id);
 -- Without a canonical product ID, a source product must retain its own ID redirect.
 new.cardmarket_url:=case when product_id is null or published_id=product_id then published_url end;
 if new.cardmarket_url is null and new.cardmarket_id>0 then
  new.cardmarket_url:='https://www.cardmarket.com/it/Pokemon/Products?idProduct='||new.cardmarket_id::text;
 end if;
 if new.cardmarket_url is not null then
  new.cardmarket_status:='linked';
  new.cardmarket_method:=case when published_url is not null and (product_id is null or published_id=product_id) then 'published_identity' else 'source_product_id' end;
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.catalog_inventory_entry_dirty()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if tg_op='DELETE' then
  update public.catalog_printing_inventory set deleted=true,image_status='missing',image_url=null,image_hd=null,image_source_url=null,reference_image_url=null,reference_source_url=null where record_key=old.entry_key;
  return old;
 end if;
 if new.verification='catalog' then
  delete from public.catalog_inventory_dirty where entry_key=new.entry_key;
  update public.catalog_printing_inventory set deleted=true,image_status='missing',image_url=null,image_hd=null,image_source_url=null,reference_image_url=null,reference_source_url=null where record_key=new.entry_key;
 else
  insert into public.catalog_inventory_dirty(entry_key) values(new.entry_key)
  on conflict(entry_key) do update set requested_at=greatest(clock_timestamp(),public.catalog_inventory_dirty.requested_at+interval '1 microsecond');
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.catalog_inventory_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if tg_op='DELETE' then raise exception 'Usare deleted=true: gli identificativi esportati non si cancellano';end if;
 if tg_op='UPDATE' then
  if new.record_key<>old.record_key then raise exception 'Identificativo inventario immutabile';end if;
  if not new.deleted and old.image_status='verified' and new.image_status<>'verified' and new.language=old.language and new.scope='printing' then
   new.image_url:=old.image_url;new.image_hd:=old.image_hd;new.image_source_url:=old.image_source_url;new.image_status:=old.image_status;new.image_evidence:=old.image_evidence;
  end if;
  if (to_jsonb(new)-'updated_at')=(to_jsonb(old)-'updated_at') then return null;end if;
  new.updated_at:=greatest(clock_timestamp(),old.updated_at+interval '1 microsecond');
 else new.updated_at:=clock_timestamp();end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.catalog_inventory_seed(batch_size integer DEFAULT 500)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare s public.catalog_inventory_state;last_key text;n integer;cap integer:=least(greatest(coalesce(batch_size,500),1),1000);
begin
 select * into s from public.catalog_inventory_state where id='inventory' for update;
 if s.seed_complete then return jsonb_build_object('complete',true,'seeded',0);end if;
 with candidates as materialized(select entry_key from public.catalog_search_entries where verification<>'catalog' and entry_key>s.seed_key order by entry_key limit cap),
 added as(insert into public.catalog_inventory_dirty(entry_key) select entry_key from candidates on conflict do nothing returning entry_key)
 select max(entry_key),count(*) into last_key,n from candidates;
 update public.catalog_inventory_state set seed_key=coalesce(last_key,seed_key),seed_complete=n<cap where id='inventory';
 return jsonb_build_object('complete',n<cap,'seeded',n);
end $function$

CREATE OR REPLACE FUNCTION public.catalog_keep_cardmarket()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if tg_op='UPDATE' then new.cardmarket_id:=coalesce(new.cardmarket_id,old.cardmarket_id);end if;
 if new.cardmarket_url is null or new.cardmarket_url !~ '^https://www[.]cardmarket[.]com/it/Pokemon/Products/[^?#]+$' then
  new.cardmarket_url:=null;
  if tg_op='UPDATE' then
   if old.cardmarket_url ~ '^https://www[.]cardmarket[.]com/it/Pokemon/Products/[^?#]+$' then new.cardmarket_url:=old.cardmarket_url;end if;
  end if;
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.catalog_link_cardmarket(batch_size integer DEFAULT 1000)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
 SET statement_timeout TO '20s'
AS $function$
declare published_count integer;entry_count integer;card_count integer; cap integer:=least(greatest(coalesce(batch_size,1000),1),5000);
begin
 with pages as (
  select cardmarket_id,min(cardmarket_url) url from public.set_carte
  where cardmarket_id>0 and cardmarket_url ~ '^https://www[.]cardmarket[.]com/it/Pokemon/Products/[^?#]+$'
  group by cardmarket_id having count(distinct cardmarket_url)=1
 ), candidates as (
  select c.sigla,c.numero,c.variante,p.url from public.set_carte c join pages p using(cardmarket_id)
  where not c.eliminata and c.cardmarket_url is null order by c.sigla,c.numero,c.variante limit cap
 ) update public.set_carte c set cardmarket_url=x.url from candidates x
 where (c.sigla,c.numero,c.variante)=(x.sigla,x.numero,x.variante);
 get diagnostics published_count=row_count;
 with candidates as (
  select e.entry_key from public.catalog_search_entries e
  left join public.catalog_export_links l on l.entry_key=e.entry_key
  left join public.set_carte c on (c.sigla,c.numero,c.variante)=(l.sigla,l.numero,l.variante) and not c.eliminata
  where e.cardmarket_status='pending' and (
   (e.verification<>'catalog' and e.source_payload->'variant'->'thirdParty'->>'cardmarket' ~ '^[1-9][0-9]{0,9}$')
   or c.cardmarket_id>0 or c.cardmarket_url is not null)
  order by e.entry_key limit cap
 ) update public.catalog_search_entries e set updated_at=clock_timestamp() from candidates x where e.entry_key=x.entry_key;
 get diagnostics entry_count=row_count;
 -- A general card gets a product link only if ALL its documented printings agree.
 -- Unknown or conflicting printings block this shortcut; their individual links remain available.
 with products as (
  select e.card_id,min(e.cardmarket_id) product_id
  from public.catalog_search_entries e
  where e.verification<>'catalog' group by e.card_id
  having bool_and(e.cardmarket_status='linked' and e.cardmarket_id is not null) and count(distinct e.cardmarket_id)=1
 ), candidates as (
  select c.id,p.product_id from public.cards c join products p on p.card_id=c.id
  where nullif(trim(c.link_cardmarket),'') is null order by c.id limit cap
 ) update public.cards c set link_cardmarket='https://www.cardmarket.com/it/Pokemon/Products?idProduct='||x.product_id::text
 from candidates x where c.id=x.id;
 get diagnostics card_count=row_count;
 return jsonb_build_object('published',published_count,'printings',entry_count,'cards',card_count);
end $function$

CREATE OR REPLACE FUNCTION public.catalog_manual_capture()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare proposed jsonb; previous jsonb; saved jsonb; field text; value jsonb;
 excluded text[]:=array['manual_overrides','created_at','updated_at','aggiornato_il','linked_at','search_text','search_vector',
 'image_attempts','image_next_attempt_at','image_last_error','traits_checked_at','traits_next_attempt_at','traits_last_error','source_updated_at'];
begin
 if tg_op='DELETE' then
  if not public.catalog_write_is_manual() and old.manual_overrides<>'{}'::jsonb then return null;end if;
  if not public.catalog_write_is_manual() and tg_table_name='cards' then
   if exists(select 1 from public.catalog_search_entries e where e.card_id=old.id and e.manual_overrides<>'{}'::jsonb) then return null;end if;
  end if;
  return old;
 end if;
 proposed:=to_jsonb(new)-excluded;
 if tg_op='UPDATE' then previous:=to_jsonb(old);saved:=old.manual_overrides;else previous:='{}';saved:='{}';end if;
 -- Nested indexing/queue updates are derived work, not new human corrections.
 if public.catalog_write_is_manual() and pg_trigger_depth()=1 then
  saved:=saved||coalesce(new.manual_overrides,'{}');
  for field,value in select * from jsonb_each(proposed) loop
   if tg_op='INSERT' or value is distinct from previous->field then
    saved:=saved||jsonb_build_object(field,value);
   end if;
  end loop;
  -- Photo state/source must agree with the manually chosen URL, including an empty URL.
  if tg_table_name='cards' and (tg_op='INSERT' or (proposed->'image_url',proposed->'image_status',proposed->'image_source') is distinct from (previous->'image_url',previous->'image_status',previous->'image_source')) then
   saved:=saved||jsonb_build_object('image_url',new.image_url,'image_status',new.image_status,'image_source',new.image_source);
  end if;
 end if;
 -- Workers cannot erase locks by sending defaults, stale metadata or an empty object.
 new.manual_overrides:=saved;
 new:=jsonb_populate_record(new,saved-excluded);
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.catalog_manual_enforce()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare parent_values jsonb; projected jsonb:='{}';
begin
 if tg_table_name='catalog_search_entries' then
  select c.manual_overrides into parent_values from public.cards c where c.id=new.card_id;
  if parent_values ? 'sigla' then projected:=projected||jsonb_build_object('set_code',parent_values->'sigla');end if;
  if parent_values ? 'nome' then projected:=projected||jsonb_build_object('name',parent_values->'nome');end if;
  if parent_values ? 'lingua' then projected:=projected||jsonb_build_object('language',parent_values->'lingua');end if;
  -- Printing-specific corrections are more specific than the parent card.
  new:=jsonb_populate_record(new,projected);
 end if;
 -- Runs after normalizers and source-derived Cardmarket/code triggers.
 new:=jsonb_populate_record(new,new.manual_overrides-array['manual_overrides','created_at','updated_at','aggiornato_il','linked_at','search_text','search_vector','image_attempts','image_next_attempt_at','image_last_error','traits_checked_at','traits_next_attempt_at','traits_last_error','source_updated_at']);
 if tg_table_name='catalog_search_entries' and (new.manual_overrides<>'{}'::jsonb or projected<>'{}'::jsonb) then
  new.search_text:=public.catalog_normalize(concat_ws(' ',new.name,new.set_code,new.collector_number,new.label,array_to_string(new.tags,' ')));
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.catalog_packaging_link_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare e public.catalog_search_entries;
begin
 if new.entry_key is not null then
  select * into e from public.catalog_search_entries where entry_key=new.entry_key;
  if not found or e.card_id<>new.card_id then raise exception 'La stampa non appartiene alla carta collegata';end if;
 end if;
 if new.status='confirmed' then
  if not exists(select 1 from public.catalog_packaging_candidates where candidate_key=new.candidate_key and review_status='confirmed') then raise exception 'Verificare prima la confezione';end if;
  if e.entry_key is null or e.verification='catalog' or e.source_payload->>'metadata_scope'='card-metadata-only'
    or coalesce((e.source_payload->>'identity_review_required')::boolean,false)
    or(e.verification<>'reviewed' and not(e.source_payload ? 'variant') and nullif(to_jsonb(e)->>'release_code','') is null) then raise exception 'Serve una stampa identificata, non una scheda generica';end if;
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.catalog_packaging_prepare()
 RETURNS trigger
 LANGUAGE plpgsql
