CREATE OR REPLACE FUNCTION public.catalog_preserve_metadata_for_legacy_writer()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare carried jsonb;codes text[];
begin
 if public.catalog_write_is_manual() or not(old.source_payload ? 'metadata_tags') or new.source_payload ? 'metadata_tags'
  or old.card_id is distinct from new.card_id or old.source_payload->>'id' is distinct from new.source_payload->>'id'
  or old.source_payload->>'source_language' is distinct from new.source_payload->>'source_language' then return new;end if;
 select coalesce(jsonb_object_agg(k,v),'{}') into carried from jsonb_each(old.source_payload)p(k,v)
 where k=any(array['types','regulationMark','stage','hp','illustrator','suffix','trainerType','energyType','metadata_tags','metadata_evidence']);
 new.source_payload:=new.source_payload||carried;
 select coalesce(array_agg(t),'{}') into codes from jsonb_array_elements_text(case when jsonb_typeof(old.source_payload->'metadata_tags')='array' then old.source_payload->'metadata_tags' else '[]'::jsonb end)t
 where split_part(t,':',1)=any(array['rarity','type','regulation','hp','stage','illustrator','category']);
 new.tags:=array(select distinct t from unnest(new.tags||codes)t order by t);
 new.search_text:=public.catalog_normalize(normalize(concat_ws(' ',new.search_text,array_to_string(codes,' ')),NFC));
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.catalog_protect_card_fields(target_card_id bigint, field_names text[], expected_values jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare c public.cards; field text; selected text[]; patch jsonb:='{}'; current_values jsonb; headers text;
 allowed text[]:=array['file_name','nome','sigla','lingua','numero','variante','codice','link_cardmarket','image_url','image_status','image_source','notes'];
begin
 if field_names is null or cardinality(field_names)=0 or jsonb_typeof(expected_values) is distinct from 'object' then raise exception 'Seleziona i campi da proteggere';end if;
 if exists(select 1 from unnest(field_names) f where f is null or not(f=any(allowed))) then raise exception 'Campo non modificabile da questa funzione';end if;
 selected:=field_names;
 if selected && array['image_url','image_status','image_source'] then selected:=selected||array['image_url','image_status','image_source'];end if;
 select array_agg(distinct f order by f) into selected from unnest(selected) f;
 select * into c from public.cards where id=target_card_id for update;
 if not found then raise exception 'Carta non trovata o non accessibile';end if;
 current_values:=to_jsonb(c);
 foreach field in array selected loop
  if not(expected_values ? field) or expected_values->field is distinct from current_values->field then
   raise exception 'Il campo % è cambiato: ricarica la carta prima di proteggerlo',field;
  end if;
  patch:=patch||jsonb_build_object(field,current_values->field);
 end loop;
 headers:=current_setting('request.headers',true);
 perform set_config('request.headers',(coalesce(nullif(headers,'')::jsonb,'{}')||jsonb_build_object('x-catalog-write-mode','manual','x-catalog-write-reason','confirm_existing_card_fields'))::text,true);
 update public.cards set manual_overrides=manual_overrides||patch where id=target_card_id returning * into c;
 if not found then raise exception 'Carta non modificabile';end if;
 perform set_config('request.headers',coalesce(headers,''),true);
 return jsonb_build_object('id',c.id,'protected_fields',selected,'manual_overrides',c.manual_overrides);
end $function$

CREATE OR REPLACE FUNCTION public.catalog_publish_coverage_audit(snapshot jsonb, quality jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if snapshot->>'contract' is distinct from 'catalog-coverage-audit-v1' or snapshot->>'complete' is distinct from 'true' or snapshot->>'generated_at' is null or jsonb_typeof(snapshot->'groups') is distinct from 'array' then raise exception 'Rilevazione incompleta: il precedente riepilogo viene mantenuto';end if;
 if quality->>'generated_at' is distinct from snapshot->>'generated_at' then raise exception 'Rilevazioni non coerenti';end if;
 insert into public.catalog_coverage_snapshots(scope,report) values('latest',snapshot) on conflict(scope) do update set report=excluded.report,updated_at=clock_timestamp();
 insert into public.catalog_quality_cache(scope,report) values('catalog',quality) on conflict(scope) do update set report=excluded.report,updated_at=clock_timestamp();
 update public.catalog_coverage_snapshots set report=jsonb_set(report,'{phase}','"complete"'::jsonb),updated_at=clock_timestamp() where scope='checkpoint';
end $function$

